import { S3, CloudFront } from "aws-sdk";
import { Bucket } from "sst/node/bucket";
import { Config } from "sst/node/config";

const cloudfront = new CloudFront();
const s3 = new S3({ apiVersion: "2006-03-01" });

export async function handler(event) {
  const path = event.path; // Ensure this ends with a slash

  await emptyS3Folder(path);
  await invalidateEntireDistribution(Config.distributionId);
}

async function emptyS3Folder(path) {
  try {
    let continuationToken;
    do {
      const listResponse = await listAllObjects(path, continuationToken);
      continuationToken = [REDACTED]
        ? listResponse.NextContinuationToken
        : null;

      if (listResponse.Contents.length > 0) {
        await deleteObjects(listResponse.Contents);
      }
    } while (continuationToken);

    console.log("All objects deleted successfully.");
  } catch (error) {
    console.error("Error deleting objects:", error);
  }
}

function listAllObjects(path, token) {
  const params = {
    Prefix: path,
    ContinuationToken: token,
    Bucket: Bucket.WebsiteBucket.bucketName,
  };

  return new Promise((resolve, reject) => {
    s3.listObjectsV2(params, function (err, data) {
      if (err) {
        reject(err);
      } else {
        resolve(data);
      }
    });
  });
}

function deleteObjects(objects) {
  const deleteParams = {
    Bucket: Bucket.WebsiteBucket.bucketName,
    Delete: {
      Objects: objects.map((obj) => ({ Key: obj.Key })),
      Quiet: true,
    },
  };

  return new Promise((resolve, reject) => {
    s3.deleteObjects(deleteParams, function (err, data) {
      if (err) {
        reject(err);
      } else {
        resolve(data);
      }
    });
  });
}

async function invalidateEntireDistribution(distributionId) {
  const params = {
    DistributionId: distributionId,
    InvalidationBatch: {
      CallerReference: `invalidate-entire-distribution-${Date.now()}`,
      Paths: {
        Quantity: 1,
        Items: [
          "/*", // This specifies that everything in the distribution should be invalidated
        ],
      },
    },
  };

  try {
    const data = await cloudfront.createInvalidation(params).promise();
    console.log(data);
  } catch (err) {
    console.error("Error invalidating distribution", err);
  }
}

import type { SSTConfig } from "sst";
import { MyStack } from "./stacks/MyStack";

export default {
  config(_input) {
    return {
      name: "social-cards",
      region: "us-east-1",
    };
  },
  stacks(app) {
    app.setDefaultRemovalPolicy("destroy");

    app.stack(MyStack, {id: "my-stack"});
  },
} satisfies SSTConfig;

import { Fn, Duration } from "aws-cdk-lib";
import * as lambda from "aws-cdk-lib/aws-lambda";
import { Api, Bucket, Config, Function, StackContext } from "sst/constructs";
import { DnsValidatedCertificate } from "aws-cdk-lib/aws-certificatemanager";
import * as cf from "aws-cdk-lib/aws-cloudfront";
import * as route53 from "aws-cdk-lib/aws-route53";
import { HttpOrigin } from "aws-cdk-lib/aws-cloudfront-origins";
import { CloudFrontTarget } from "aws-cdk-lib/aws-route53-targets";

const rootDomain = "sst.dev";
const domainName = `social-cards.${rootDomain}`;
const layerArn =
  "arn:aws:lambda:us-east-1:764866452798:layer:chrome-aws-lambda:22";

export function MyStack({ stack, app }: StackContext) {
  let hostedZone;
  let domainProps = {};

  const useCustomDomain = app.stage === "prod" || app.stage === "main";

  const layerChromium = new lambda.LayerVersion(stack, "chromiumLayers", {
    code: lambda.Code.fromAsset("layers/chromium"),
  });

  // Create S3 bucket to store generated images
  const bucket = new Bucket(stack, "WebsiteBucket");

  // Create a HTTP API
  const api = new Api(stack, "Api", {
    routes: {
      "GET /{template}/{file}": {
        function: {
          handler: "src/lambda.handler",
          // Increase the timeout for generating screenshots
          timeout: "15 minutes",
          // Increase disk size
          diskSize: "4 GB",
          // Increase the memory
          memorySize: "4 GB",
          // Load Chrome in a Layer
          layers: [layerChromium],
          // Copy over templates and non Latin fonts
          copyFiles: [
            {
              from: "templates",
              to: "templates",
            },
            {
              from: ".fonts",
              to: ".fonts",
            },
          ],
          nodejs: {
            esbuild: {
              // Exclude bundling it in the Lambda function
              external: ["@sparticuz/chromium"],
            },
          },
        },
      },
    },
  });

  api.bind([bucket]);

  if (useCustomDomain) {
    // Lookup domain hosted zone
    hostedZone = route53.HostedZone.fromLookup(stack, "HostedZone", {
      domainName: rootDomain,
    });

    // Create ACM certificate
    const certificate = new DnsValidatedCertificate(stack, "Certificate", {
      domainName,
      hostedZone,
      region: "us-east-1",
    });

    domainProps = {
      ...domainProps,
      certificate,
      domainNames: [domainName],
    };
  }

  // Create CloudFront Distribution
  const distribution = new cf.Distribution(stack, "WebsiteCdn", {
    ...domainProps,
    defaultBehavior: {
      origin: new HttpOrigin(Fn.parseDomainName(api.url)),
      viewerProtocolPolicy: cf.ViewerProtocolPolicy.REDIRECT_TO_HTTPS,
      cachePolicy: new cf.CachePolicy(stack, "WebsiteCachePolicy", {
        // Set cache duration to 1 year
        minTtl: Duration.seconds(31536000),
        // Forward the query string to the origin
        queryStringBehavior: cf.CacheQueryStringBehavior.all(),
      }),
    },
  });

  if (useCustomDomain) {
    // Create DNS record
    new route53.ARecord(stack, "AliasRecord", {
      zone: hostedZone,
      recordName: domainName,
      target: route53.RecordTarget.fromAlias(
        new CloudFrontTarget(distribution)
      ),
    });
  }

  // Create Function to clear the cache
  const clearFunction = new Function(stack, "ClearCache", {
    handler: "src/clear-cache.handler",
    permissions: ["cloudfront:CreateInvalidation"],
  });

  clearFunction.bind([
    bucket,
    new Config.Parameter(stack, "distributionId", {
      value: distribution.distributionId,
    }),
  ]);

  // Show the endpoint in the output
  stack.addOutputs({
    ApiEndpoint: api.url,
    BucketName: bucket.bucketName,
    SiteEndpoint: `https://${useCustomDomain ? domainName : distribution.distributionDomainName
      }`,
  });
}

import path from "path";
import { S3 } from "aws-sdk";
import puppeteer from "puppeteer-core";
import { Bucket } from "sst/node/bucket";
import chromium from "@sparticuz/chromium";

const ext = "png";
const ContentType = `image/${ext}`;
const s3 = new S3({ apiVersion: "2006-03-01" });

// This is the path to the local Chromium binary
const YOUR_LOCAL_CHROMIUM_PATH =
  "/tmp/localChromium/chromium/mac_arm-1471750/chrome-mac/Chromium.app/Contents/MacOS/Chromium";
//"/tmp/localChromium/chromium/mac-1165945/chrome-mac/Chromium.app/Contents/MacOS/Chromium";

export async function handler(event) {
  const { file, template } = event.pathParameters;

  const title = parseTitle(file);

  // Check if it's a valid request
  if (file === null) {
    return createErrorResponse();
  }

  const options = event.rawQueryString;
  const key = generateS3Key(template, title, options);

  // Check the S3 bucket
  const fromBucket = await get(key);

  // Return from the bucket
  if (fromBucket) {
    return createResponse(fromBucket);
  }

  const browser = await puppeteer.launch({
    args: chromium.args,
    defaultViewport: chromium.defaultViewport,
    executablePath: process.env.IS_LOCAL
      ? YOUR_LOCAL_CHROMIUM_PATH
      : await chromium.executablePath(),
    headless: chromium.headless,
  });

  const page = await browser.newPage();

  await page.setViewport({
    width: 1200,
    height: 630,
  });

  // Navigate to the url
  await page.goto(
    `file:${path.join(
      process.cwd(),
      `templates/${template}.html`,
    )}?title=${encodeURIComponent(title)}${options ? "&" + options : ""}`,
  );

  // Wait for page to complete loading
  await page.evaluate("document.fonts.ready");

  // Take screenshot
  const buffer = await page.screenshot();

  // Upload to the bucket
  await upload(key, buffer);

  return createResponse(buffer);
}

/**
 * Parse a base64 url encoded string of the format
 *
 * $title.png
 *
 */
function parseTitle(file) {
  const extension = `.${ext}`;

  if (!file.endsWith(extension)) {
    return null;
  }

  // Remove the .png extension
  const encodedTitle = file.slice(0, -1 * extension.length);

  const buffer = Buffer.from(encodedTitle, "base64");

  const decoded = buffer.toString("utf8");

  try {
    return decodeURIComponent(decoded);
  } catch {
    return decoded;
  }
}

/**
 * Generate a S3 safe key using the path parameters and query string options
 */
function generateS3Key(template, title, options) {
  const parts = [
    template,
    ...(options !== "" ? [encodeURIComponent(options)] : []),
    `${encodeURIComponent(title)}.${ext}`,
  ];

  return parts.join("/");
}

async function upload(Key, Body) {
  const params = {
    Key,
    Body,
    ContentType,
    Bucket: Bucket.WebsiteBucket.bucketName,
  };

  await s3.putObject(params).promise();
}

async function get(Key) {
  // Disabling S3 lookup on local
  if (process.env.IS_LOCAL) {
    return null;
  }

  const params = { Key, Bucket: Bucket.WebsiteBucket.bucketName };

  try {
    const { Body } = await s3.getObject(params).promise();
    return Body;
  } catch (e) {
    return null;
  }
}

function createResponse(buffer) {
  return {
    statusCode: 200,
    // Return as binary data
    isBase64Encoded: true,
    body: buffer.toString("base64"),
    headers: { "Content-Type": ContentType },
  };
}

function createErrorResponse() {
  return {
    statusCode: 500,
    body: "Invalid request",
  };
}
